import re
import os

def task_func(request):
    def error_response(status, message):
        return f"HTTP/1.1 {status}\r\n\r\n{message}"

    if not isinstance(request, str) or not request.strip():
        return error_response("400 Bad Request", "Bad Request")

    request_line = request.splitlines()[0].strip()
    match = re.fullmatch(r"GET\s+(\S+)\s+HTTP/(1\.[01])", request_line)
    if not match:
        return error_response("400 Bad Request", "Bad Request")

    raw_path = match.group(1).split("?", 1)[0].split("#", 1)[0].replace("\\", "/")

    if not raw_path.startswith("/"):
        return error_response("400 Bad Request", "Bad Request")
    if raw_path == "/":
        return error_response("400 Bad Request", "Bad Request")
    if re.search(r"(^|/)\.\.(/|$)", raw_path):
        return error_response("400 Bad Request", "Bad Request")

    rel_path = raw_path.lstrip("/")
    if not rel_path or ":" in rel_path:
        return error_response("400 Bad Request", "Bad Request")

    base_dir = os.path.realpath(os.getcwd())
    target_path = os.path.realpath(os.path.join(base_dir, rel_path))

    try:
        if os.path.commonpath([base_dir, target_path]) != base_dir:
            return error_response("400 Bad Request", "Bad Request")
    except ValueError:
        return error_response("400 Bad Request", "Bad Request")

    if not os.path.isfile(target_path):
        return error_response("404 Not Found", "Not Found")

    try:
        with open(target_path, "rb") as f:
            content_bytes = f.read()
    except PermissionError:
        return error_response("403 Forbidden", "Forbidden")
    except OSError:
        return error_response("500 Internal Server Error", "Internal Server Error")

    try:
        content = content_bytes.decode("utf-8")
    except UnicodeDecodeError:
        content = content_bytes.decode("latin-1")

    return f"HTTP/1.1 200 OK\r\nContent-Length: {len(content_bytes)}\r\n\r\n{content}"

