import base64
import hashlib
import os

def task_func(password, SALT_LENGTH = 32):
    if password is None:
        raise ValueError("password must not be None")

    if SALT_LENGTH <= 0:
        raise ValueError("SALT_LENGTH must be a positive integer")

    if isinstance(password, str):
        if password == "":
            raise ValueError("password must not be empty")
        password_bytes = password.encode("utf-8")
    elif isinstance(password, (bytes, bytearray, memoryview)):
        if len(password) == 0:
            raise ValueError("password must not be empty")
        password_bytes = bytes(password)
    else:
        raise TypeError("password must be a str or bytes-like object")

    salt = os.urandom(SALT_LENGTH)
    iterations = 100000
    derived_key = hashlib.pbkdf2_hmac("sha256", password_bytes, salt, iterations)

    return base64.b64encode(salt), base64.b64encode(derived_key)

