import urllib.request
from bs4 import BeautifulSoup
import csv
import os
# Constants
CSV_FILE_PATH = 'scraped_data.csv'

def task_func(url):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    url = url.strip()
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    def _clean_text(node):
        if node is None:
            return ""
        return " ".join(node.get_text(" ", strip=True).split())

    def _unique_headers(headers):
        seen = {}
        unique = []
        for header in headers:
            name = (header or "").strip() or "column"
            count = seen.get(name, 0)
            if count:
                unique_name = f"{name}_{count + 1}"
            else:
                unique_name = name
            seen[name] = count + 1
            unique.append(unique_name)
        return unique

    html_text = ""
    error_message = None

    try:
        request = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(request, timeout=20) as response:
            raw = response.read()
            charset = response.headers.get_content_charset() or "utf-8"
            html_text = raw.decode(charset, errors="replace")
    except Exception as exc:
        error_message = str(exc)

    records = []
    soup = BeautifulSoup(html_text, "html.parser") if html_text else None

    if soup is not None:
        tables = soup.find_all("table")
        for table_index, table in enumerate(tables):
            rows = table.find_all("tr")
            if not rows:
                continue

            # Build row-wise cell text first.
            extracted_rows = []
            for row in rows:
                cells = row.find_all(["th", "td"])
                if not cells:
                    continue
                extracted_rows.append([_clean_text(cell) for cell in cells])

            if not extracted_rows:
                continue

            # Prefer explicit header rows with <th>; otherwise use the first row
            # as headers if there are multiple rows. If there is only one row,
            # treat it as data with generated column names.
            header_row_index = None
            headers = []

            for i, row in enumerate(rows):
                if row.find_all("th"):
                    headers = [_clean_text(cell) for cell in row.find_all(["th", "td"])]
                    header_row_index = i
                    break

            if not headers:
                if len(extracted_rows) > 1:
                    headers = extracted_rows[0]
                    header_row_index = 0
                else:
                    max_cols = max(len(r) for r in extracted_rows)
                    headers = [f"col_{i + 1}" for i in range(max_cols)]
                    header_row_index = None

            headers = _unique_headers(headers)

            # Store data rows, padding/trimming to match headers.
            data_row_number = 0
            for i, row_values in enumerate(extracted_rows):
                if header_row_index is not None and i == header_row_index:
                    continue

                if len(row_values) > len(headers):
                    for extra_index in range(len(headers), len(row_values)):
                        headers.append(f"col_{extra_index + 1}")
                elif len(row_values) < len(headers):
                    row_values = row_values + [""] * (len(headers) - len(row_values))

                data_row_number += 1
                record = {
                    "table_index": table_index,
                    "row_index": data_row_number,
                }
                for header, value in zip(headers, row_values):
                    record[header] = value
                records.append(record)

        if not records:
            fallback_records = []

            title = _clean_text(soup.title) if soup.title else ""
            if title:
                fallback_records.append(
                    {"content_type": "title", "text": title, "href": ""}
                )

            for tag_name in ["h1", "h2", "h3", "h4", "h5", "h6", "p", "li"]:
                for tag in soup.find_all(tag_name):
                    text = _clean_text(tag)
                    if text:
                        fallback_records.append(
                            {"content_type": tag_name, "text": text, "href": ""}
                        )

            for link in soup.find_all("a", href=True):
                text = _clean_text(link)
                href = link.get("href", "").strip()
                if text or href:
                    fallback_records.append(
                        {"content_type": "link", "text": text, "href": href}
                    )

            records = fallback_records

    if not records:
        if error_message:
            records = [{"content_type": "error", "text": error_message, "href": ""}]
        else:
            records = [{"content_type": "empty", "text": "", "href": ""}]

    directory = os.path.dirname(CSV_FILE_PATH)
    if directory:
        os.makedirs(directory, exist_ok=True)

    fieldnames = []
    seen_fields = set()
    for record in records:
        for key in record.keys():
            if key not in seen_fields:
                seen_fields.add(key)
                fieldnames.append(key)

    with open(CSV_FILE_PATH, "w", newline="", encoding="utf-8") as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(records)

    return CSV_FILE_PATH

