import json
import csv
import os
import base64

def task_func(raw_string, filename, output_dir):
    """
    Decode a base64-encoded JSON string, save the data into a CSV file,
    and return the resulting file path.
    """
    if not isinstance(filename, str) or not filename.strip():
        raise ValueError("filename must be a non-empty string")
    if not isinstance(output_dir, str) or not output_dir.strip():
        raise ValueError("output_dir must be a non-empty string")

    output_dir = output_dir.strip()
    os.makedirs(output_dir, exist_ok=True)

    filename = filename.strip()
    if not filename.lower().endswith(".csv"):
        filename += ".csv"
    file_path = os.path.join(output_dir, filename)

    if isinstance(raw_string, str):
        raw_bytes = "".join(raw_string.split()).encode("utf-8")
    elif isinstance(raw_string, (bytes, bytearray)):
        raw_bytes = b"".join(bytes(raw_string).split())
    else:
        raise ValueError("raw_string must be a base64-encoded string or bytes")

    if not raw_bytes:
        raise ValueError("raw_string must be a non-empty base64 string")

    try:
        decoded_bytes = base64.b64decode(raw_bytes, validate=True)
    except Exception as exc:
        raise ValueError("Invalid base64 input") from exc

    try:
        decoded_text = decoded_bytes.decode("utf-8")
    except Exception as exc:
        raise ValueError("Decoded content is not valid UTF-8") from exc

    try:
        data = json.loads(decoded_text)
    except Exception as exc:
        raise ValueError("Decoded content is not valid JSON") from exc

    def _serialize(value):
        if value is None:
            return ""
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False)
        return str(value)

    with open(file_path, "w", newline="", encoding="utf-8") as csvfile:
        writer = csv.writer(csvfile)

        if isinstance(data, list):
            if data and all(isinstance(item, dict) for item in data):
                headers = []
                seen = set()
                for item in data:
                    for key in item.keys():
                        if key not in seen:
                            seen.add(key)
                            headers.append(key)

                if headers:
                    writer.writerow(headers)
                    for item in data:
                        writer.writerow([_serialize(item.get(key)) for key in headers])
            else:
                writer.writerow(["value"])
                for item in data:
                    writer.writerow([_serialize(item)])

        elif isinstance(data, dict):
            writer.writerow(["key", "value"])
            for key, value in data.items():
                writer.writerow([str(key), _serialize(value)])

        else:
            writer.writerow(["value"])
            writer.writerow([_serialize(data)])

    return file_path

