import subprocess
import os
import signal
import time

def task_func(process_name: str) -> int:
    target = (process_name or "").strip()
    if not target:
        return 0

    current_pid = os.getpid()

    def base_name(name: str) -> str:
        name = (name or "").strip()
        if not name:
            return ""
        return name.replace("\\", "/").rsplit("/", 1)[-1]

    def matches(candidate: str) -> bool:
        cand_base = base_name(candidate)
        target_base = base_name(target)
        if not cand_base or not target_base:
            return False

        if os.name == "nt":
            cand_stem = os.path.splitext(cand_base)[0].lower()
            target_stem = os.path.splitext(target_base)[0].lower()
            return cand_stem == target_stem

        return cand_base == target_base

    pids = set()

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/fo", "csv", "/nh"],
                capture_output=True,
                text=True,
                check=False,
            )
            for line in result.stdout.splitlines():
                line = line.strip()
                if not line:
                    continue
                if line.startswith('"') and line.endswith('"'):
                    line = line[1:-1]
                parts = line.split('","')
                if len(parts) < 2:
                    continue
                image_name = parts[0].strip('"')
                pid_part = parts[1].strip('"')
                try:
                    pid = int(pid_part)
                except ValueError:
                    continue
                if pid != current_pid and matches(image_name):
                    pids.add(pid)
        else:
            proc_dir = "/proc"
            if os.path.isdir(proc_dir):
                for entry in os.listdir(proc_dir):
                    if not entry.isdigit():
                        continue
                    pid = int(entry)
                    if pid == current_pid:
                        continue

                    candidate = ""
                    exe_path = os.path.join(proc_dir, entry, "exe")
                    try:
                        candidate = os.readlink(exe_path)
                    except OSError:
                        comm_path = os.path.join(proc_dir, entry, "comm")
                        try:
                            with open(comm_path, "r", encoding="utf-8", errors="ignore") as f:
                                candidate = f.read().strip()
                        except OSError:
                            continue

                    if matches(candidate):
                        pids.add(pid)
            else:
                result = subprocess.run(
                    ["ps", "-eo", "pid=,args="],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    pid_part, cmd = parts
                    try:
                        pid = int(pid_part)
                    except ValueError:
                        continue
                    if pid == current_pid:
                        continue
                    first = cmd.split(None, 1)[0].strip('"\'')

                    if matches(first):
                        pids.add(pid)
    except Exception:
        return 0

    if not pids:
        return 0

    stopped = 0
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (ProcessLookupError, PermissionError, OSError):
            pass

    time.sleep(1)
    return stopped

