import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist or is not a directory: {src_folder}",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception as exc:
        return {
            "success": False,
            "message": f"Failed to prepare destination folder: {exc}",
            "failed_files": [],
        }

    # Collect regular files in the source folder, including hidden files.
    src_paths = []
    seen = set()
    for pattern in (os.path.join(src_folder, "*"), os.path.join(src_folder, ".*")):
        for path in glob(pattern):
            if path not in seen and os.path.isfile(path):
                seen.add(path)
                src_paths.append(path)

    src_paths.sort()
    total_files = len(src_paths)

    if total_files == 0:
        return {
            "success": True,
            "message": "No files to compress.",
            "failed_files": [],
        }

    if shutil.which("gzip") is None:
        return {
            "success": False,
            "message": "gzip command not found; no files were compressed.",
            "failed_files": [os.path.basename(p) for p in src_paths],
        }

    succeeded = 0

    for src_path in src_paths:
        filename = os.path.basename(src_path)
        final_path = os.path.join(dst_folder, filename + ".gz")
        temp_path = os.path.join(dst_folder, f".{filename}.gz.{os.getpid()}.tmp")

        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)

            with open(temp_path, "wb") as out_file:
                proc = subprocess.Popen(
                    ["gzip", "-c", src_path],
                    stdout=out_file,
                    stderr=subprocess.PIPE,
                )
                _, stderr = proc.communicate()

            if proc.returncode != 0:
                err_text = stderr.decode("utf-8", errors="replace").strip()
                raise RuntimeError(err_text or f"gzip failed for {filename}")

            os.replace(temp_path, final_path)
            succeeded += 1

        except Exception:
            failed_files.append(filename)
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except OSError:
                pass

    success = len(failed_files) == 0
    if success:
        message = f"Compressed and moved {succeeded} file(s) successfully."
    else:
        message = (
            f"Compressed and moved {succeeded} of {total_files} file(s) successfully; "
            f"{len(failed_files)} file(s) failed."
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

