import hashlib
import binascii

def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError

    def quote_ident(name):
        return '"' + name.replace('"', '""') + '"'

    def sha256_hex(value):
        digest = hashlib.sha256(value.encode("utf-8")).digest()
        return binascii.hexlify(digest).decode("ascii")

    tables = [
        row[0]
        for row in cursor.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
    ]

    def table_key(name):
        lname = name.lower()
        if lname in ("user", "users"):
            return (0, lname)
        if "user" in lname:
            return (1, lname)
        return (2, lname)

    for table in sorted(tables, key=table_key):
        info = cursor.execute(f"PRAGMA table_info({quote_ident(table)})").fetchall()
        if not info:
            continue

        col_names = [row[1] for row in info]
        lower_to_name = {name.lower(): name for name in col_names}

        password_col = None
        for candidate in ("password", "passwd", "pwd"):
            if candidate in lower_to_name:
                password_col = lower_to_name[candidate]
                break
        if password_col is None:
            continue

        pk_cols = [row[1] for row in info if row[5]]
        updated = 0

        if pk_cols:
            select_cols = ", ".join(quote_ident(col) for col in pk_cols + [password_col])
            rows = cursor.execute(
                f"SELECT {select_cols} FROM {quote_ident(table)}"
            ).fetchall()

            where_clause = " AND ".join(f"{quote_ident(col)} = ?" for col in pk_cols)
            update_sql = (
                f"UPDATE {quote_ident(table)} "
                f"SET {quote_ident(password_col)} = ? "
                f"WHERE {where_clause}"
            )

            for row in rows:
                old_password = "" if row[-1] is None else str(row[-1])
                hashed = sha256_hex(salt + old_password)
                cursor.execute(update_sql, (hashed, *row[:-1]))
                updated += 1
        else:
            rows = cursor.execute(
                f"SELECT rowid, {quote_ident(password_col)} FROM {quote_ident(table)}"
            ).fetchall()
            update_sql = (
                f"UPDATE {quote_ident(table)} "
                f"SET {quote_ident(password_col)} = ? "
                f"WHERE rowid = ?"
            )

            for rowid, old_password in rows:
                old_password = "" if old_password is None else str(old_password)
                hashed = sha256_hex(salt + old_password)
                cursor.execute(update_sql, (hashed, rowid))
                updated += 1

        connection = getattr(cursor, "connection", None)
        if connection is not None:
            try:
                connection.commit()
            except Exception:
                pass

        return updated

    return 0

