import json
import re
import pandas as pd

def task_func(json_str):
    if not isinstance(json_str, str):
        return pd.DataFrame()

    json_str = json_str.strip()
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except Exception:
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    number_pattern = r'[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?'

    def normalize_atom(value):
        if isinstance(value, bool) or value is None:
            return value
        if isinstance(value, (int, float)):
            return float(value) * 2.0
        if isinstance(value, str):
            match = re.search(number_pattern, value)
            if match:
                try:
                    return float(match.group(0)) * 2.0
                except ValueError:
                    return value
            return value
        return value

    normalized = {}
    list_lengths = set()

    for key, value in data.items():
        if isinstance(value, dict):
            return pd.DataFrame()

        if isinstance(value, list):
            normalized_list = []
            for item in value:
                if isinstance(item, (dict, list)):
                    return pd.DataFrame()
                normalized_list.append(normalize_atom(item))
            normalized[key] = normalized_list
            list_lengths.add(len(normalized_list))
        else:
            normalized[key] = normalize_atom(value)

    if not normalized:
        return pd.DataFrame()

    if list_lengths:
        if len(list_lengths) != 1:
            return pd.DataFrame()

        row_count = next(iter(list_lengths))
        for key, value in list(normalized.items()):
            if not isinstance(value, list):
                normalized[key] = [value] * row_count
            elif len(value) != row_count:
                return pd.DataFrame()

        return pd.DataFrame(normalized)

    return pd.DataFrame([normalized])

