from collections import Counter

def task_func(mystrings, text):
    def _is_empty(value):
        if value is None:
            return True
        if isinstance(value, str):
            return value.strip() == ""
        try:
            return len(value) == 0
        except TypeError:
            return False

    if _is_empty(text):
        raise ValueError("Input text is empty")

    if isinstance(text, str):
        fallback_words = [token for token in re.split(r"\s+", text.strip()) if token]
    else:
        try:
            fallback_words = list(text)
