import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"

def task_func(interval, duration):
    interval = float(interval)
    duration = float(duration)
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    def _ensure_text(output):
        if isinstance(output, bytes):
            return output.decode("utf-8", errors="ignore")
        return str(output)

    def _extract_cpu_usage_from_line(line):
        normalized = line.lower()
        for ch in "(),:%=":
            normalized = normalized.replace(ch, " ")
        parts = normalized.split()

        for idx, part in enumerate(parts):
            if part in ("idle", "id") and idx > 0:
                try:
                    idle = float(parts[idx - 1])
                except ValueError:
                    continue
                return max(0.0, min(100.0, 100.0 - idle))
        return None

    def _get_cpu_usage():
        system = platform.system().lower()

        try:
            if system.startswith("win"):
                output = subprocess.check_output(
                    ["wmic", "cpu", "get", "loadpercentage", "/value"],
                    stderr=subprocess.DEVNULL,
                    text=True,
                )
                output = _ensure_text(output)
                for line in output.splitlines():
                    if "loadpercentage" in line.lower():
                        try:
                            return max(0.0, min(100.0, float(line.split("=", 1)[1].strip())))
                        except (IndexError, ValueError):
                            continue
            else:
                commands = (
                    ["sh", "-c", "LC_ALL=C top -bn1 2>/dev/null"],
                    ["sh", "-c", "LC_ALL=C top -l 1 2>/dev/null"],
                )
                for cmd in commands:
                    try:
                        output = subprocess.check_output(
                            cmd, stderr=subprocess.DEVNULL, text=True
                        )
                    except Exception:
                        continue

                    output = _ensure_text(output)
                    for line in output.splitlines():
                        if "cpu" in line.lower():
                            usage = _extract_cpu_usage_from_line(line)
                            if usage is not None:
                                return usage
        except Exception:
            pass

        return 0.0

    records = []
    start_time = time.monotonic()
    next_sample_time = start_time

    while True:
        now = time.monotonic()
        if now - start_time > duration:
            break

        records.append(
            {
                "timestamp": time.time(),
                "cpu_usage": _get_cpu_usage(),
            }
        )

        next_sample_time += interval
        sleep_time = next_sample_time - time.monotonic()
        if sleep_time > 0:
            time.sleep(sleep_time)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as file:
            json.dump(records, file)
    except OSError:
        return None

    return LOGFILE_PATH
